public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    DeletionPolicy delegate = new FileDeleteOnExitDeletionPolicy();
    FileFilter filter = new FileFilter() {
        @Override
        public boolean accept(File pathname) {
            return mostlyEmpty(pathname) || pathname.isDirectory();
        }
    };
    new FileVerification(Files.walkFileTree(file, filter)).verify();
    Files.walkFileTree(file, filter, new SimpleFileVisitor<Path>() {
        @Override
        public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
            boolean forceDeleted = false;
            try {
                forceDeleted = Files.deleteOnExit(file);
                Files.delete(file.toPath()); // Force delete the original file
            } catch (IOException x) {
                if (!forceDeleted) {
                    throw x;
                }
            }
            return FileVisitResult.CONTINUE;
        }

        @Override
        public FileVisitResult postVisitDirectory(Path dir, IOException x) throws IOException {
            if (x != null) {
                throw x;
            }
            try {
                Files.deleteOnExit(dir);
                Files.delete(dir.toPath()); // Force delete the original directory
            } catch (IOException x) {
                if (!forceDeleted) {
                    throw x;
                }
            }
            return FileVisitResult.CONTINUE;
        }
    });
}

