public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    long size = schema.getSerializedSize(message);
    out.writeVarInt32((int) size);
    out.writeBytes(schema.serialize(message, buffer));
    return (int) size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (message == null) {
        byte[] sizeBytes = schema.getSizeBytes(0);
        out.write(sizeBytes);
        return sizeBytes.length;
    } else {
        byte[] messageBytes = schema.encode(message);
        byte[] sizeBytes = schema.getSizeBytes(messageBytes.length);
        out.write(sizeBytes);
        out.write(messageBytes);
        return sizeBytes.length + messageBytes.length;
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] messageBytes = message.writeDelimited(schema);
    out.write(Integer.valueOf(messageBytes.length).toByteArray());
    out.write(messageBytes);
    return messageBytes.length;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message length to the stream
    out.write(Ints.toByteArray(schema.getLength(message)));

    // Serialize the message itself into the stream
    schema.writeTo(out, message, buffer);

    // Consume the buffer to any remaining bytes from the last read operation
    buffer.consume(anyRemaining);

    return schema.getLength(message) + buffer.length();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.toMessageBytes(message, buffer);
    out.write(size >>> 24);
    out.write(size >>> 16);
    out.write(size >>> 8);
    out.write(size & 0xFF);
    out.write(buffer.array());
    return size;
}

