public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }

        Type[] parameterTypes = ((ParameterizedType) genericType).getActualTypeArguments();

        // Handle the case when genericType is a raw type
        if (parameterTypes == null || parameterTypes.length == 0) {
            return null;
        }

        List<Class<?>> resolvedArguments = new ArrayList<>();
        for (Type argument : parameterTypes) {
            if (argument instanceof Class<?>) {
                resolvedArguments.add((Class<?>) argument);
            }
        }

        return resolvedArguments.toArray(new Class[0]);
    }

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if genericType is not parameterized
    if (genericType instanceof ParameterizedType) {
        Type ownerType = ((ParameterizedType) genericType).getOwnerType();
        if (ownerType != null) {
            return resolveArguments(ownerType, targetType);
        }
    }
    return new Class<?>[0];
}

private static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null; // Generic type not parameterized
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    if (actualTypeArguments.length > 0) {
        // Create an array of Class<?> for each actual type argument
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            if (actualTypeArguments[i] instanceof ParameterizedType) {
                // Recursively resolve nested types
                resolvedArguments[i] = resolveArguments(actualTypeArguments[i], targetType);
            } else if (actualTypeArguments[i] instanceof TypeVariable) {
                // Resolve type variables using type information of the target type
                TypeVariable<?> var = (TypeVariable<?>) actualTypeArguments[i];
                for (Type homogeneusType : targetType.getClassGenerics()) {
                    if (var.equals(homogeneusType)) {
                        resolvedArguments[i] = homogeneusType;
                        break;
                    }
                }
            } else {
                // Simple type argument
                resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
            }
        }
        return resolvedArguments;
    } else {
        return null; // No actual type arguments
    }
}

