static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be greater than 0");
    }
    long years = timeBucket / (365 * dayStep);
    long months = (timeBucket % (365 * dayStep)) / 30 * dayStep;
    long days = timeBucket % (365 * dayStep) % 30 * dayStep;
    return years * (365 * dayStep) + months * 30 * dayStep + days;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int quotient = (int) (timeBucket / dayStep);
    if (timeBucket % dayStep == 0) {
        return quotient * dayStep;
    } else {
        return (quotient + 1) * dayStep;
    }
}

