}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
  // Initialize size counter and position
  int size = 0;
  int pos = index;

  // Loop through characters in the sequence
  while (pos < index + len) {
    final int b = (byte) str.charAt(pos);
    pos++;

    // Check if character is a single-byte character
    if (b >= 0 && b < 128) {
      size += 1;
      continue;
    }

    // Check if character is a multi-byte character
    if (b >= 0xe0 && b < 0xf0) {
      size += 2;
      if (pos < index + len) {
        b = (byte) str.charAt(pos);
        pos++;
      }
      if (pos < index + len) {
        b = (byte) str.charAt(pos);
        pos++;
      }
    } else if (b >= 0xc0 && b < 0xe0) {
      size += 1;
      if (pos < index + len) {
        b = (byte) str.charAt(pos);
        pos++;
      }
    } else if (b >= 0x80 && b < 0xc0) {
      size += 1;
      if (pos < index + len) {
        b = (byte) str.charAt(pos);
        pos++;
      }
      if (pos < index + len) {
        b = (byte) str.charAt(pos);
        pos++;
      }
    }
  }

  return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        int codePoint = str.codePointAt(i);
        if (codePoint >= 0xD800 && codePoint <= 0xDBFF) {
            if (i + 1 < len && str.codePointAt(i + 1) >= 0xDC00 && str.codePointAt(i + 1) <= 0xDFFF) {
                size += 2;
                i++;
            } else {
               throw new IllegalArgumentException("Multibyte sequence is not complete in the middle of the string");
            }
        } else {
            size++;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int i = index;
    while (i < index + len) {
        int u = str.charAt(i);
        if (u >= 0 && u <= 127) {
            size++;
        } else if (u >= 128 && u <= 191) {
            size += 2;
        } else if (u >= 192 && u <= 223) {
            size += 3;
        } else if (u >= 224 && u <= 239) {
            size += 4;
        } else if (u >= 240 && u <= 244) {
            size += 5;
        } else if (u >= 245 && u <= 248) {
            size += 6;
        } else if (u >= 249 && u <= 252) {
            size += 7;
        } else {
            size += 8;
        }
        i++;
    }
    return size;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
  int size = 0;
  for (int i = index; i < index + len; i++) {
    char c = str.charAt(i);
    if (c <= 0x7F) { // 0xxxxxxx
      size++;
    } else if (c <= 0x7FF) { // 110yyyyy 10xxxxxx
      size += 2;
    } else if (c <= 0xFFFF) { // 1110yyyy 10yyyyyy 10xxxxxx
      size += 3;
    } else { // 11110yyy 10yyyyyy 10yyyyyy 10xxxxxx
      size += 4;
    }
  }
  return size;
}

