        throw new IndexOutOfBoundsException("byteOffset is out of bounds for the array");
    }

    // Ensure that byteLength does not exceed the remaining space in byteArrayValue
    int remaining = byteArrayValue.length - byteOffset;
    if (byteLength > remaining) {
        throw new IllegalArgumentException("byteLength is too large");
    }

    // Create a new or expand the ByteVector to match byteLength
    if (!this.isAllocated || this.size < byteLength) {
        this.ensureCapacity(byteLength);
