public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb){
    for (int i = 0; i < str.length(); i++) {
        int byteValue = str.charAt(i);
        if (byteValue <= 127) { // Printable ASCII ASCII
            lb.write((byte) byteValue);
        } else if (byteValue <= 2047) { // ASCII Large
            lb.write((byte) (0xc0 | (byteValue >> 6)));
            lb.write((byte) (0x80 | (byteValue & 0x3f)));
        } else if (byteValue <= 65535) { // Unicode Large
            lb.write((byte) (0xe0 | (byteValue >> 12)));
            lb.write((byte) (0x80 | ((byteValue >> 6) & 0x3f)));
            lb.write((byte) (0x80 | (byteValue & 0x3f)));
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    try {
        int len = str.length();
        if ( len > 1024) {
            throw new UnsupportedOperationException(" UTF8 encoding for long strings is not supported yet");
        }

        Buffer buffer = session.getBuffer(str.length());
        int offset = 0;
        while (offset < len) {
            int bytesWritten = str.subSequence(offset, Math.min(len, offset + 31)).getBytes(StandardCharsets.UTF_8).length;
            buffer.put(offset, bytesWritten);
            buffer.put(offset + 1, str.subSequence(offset, offset + 31).charAt(0));
            offset += bytesWritten + 1;
        }

        lb.putAll(buffer.slice(offset - str.length(), offset));
        return lb;
    } catch (IOException e) {
        // Handle exception, for example, by logging or handling it with a default behavior
        e.printStackTrace();
        return lb;
    }
}

