public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    checkNotNull(out, "Output stream must not be null.");
    checkNotNull(node, "LinkedBuffer must not be null.");

    int offset = 0;
    int contentSize = calculateContentSize(node);
    out.writeInt(contentSize);

    byte[] buffer = node.getBuffer();
    out.write(buffer, 0, buffer.length);

    offset += contentSize;

    return offset;
}

private static int calculateContentSize(LinkedBuffer node) {
    int size = 0;
    for (int i = 0; i < node.size(); i++) {
        size += 4; // For the length of each element
        size += node.get(i).length; // For the element data
        size += 4; // For the type of the element
    }
    return size;
}

