public static int writeTo(final DataOutput out,LinkedBuffer node) throws IOException {
    if (out == null || node == null) {
        throw new IllegalArgumentException("Input can't be null");
    }
    int totalSize = 0;
    boolean hasLinkData = false;
    boolean hasNodeData = false;
    while (node != null) {
        // Write node data
        node.writeTo(out);
        totalSize += node.getSize();
        hasNodeData = true;

        // Write link data
        if (node.hasLinks()) {
            LinkedBuffer linkedBuffer = node.getLinks();
            for (LinkedBuffer link : linkedBuffer) {
                link.writeTo(out);
                totalSize += link.getSize();
                hasLinkData = true;
            }
        }
        node = node.getNext();
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalContentSize = node.getLength();
    byte[] data = node.getData();
    int sizeInBytes = data.length;
    out.writeInt(sizeInBytes);
    out.write(data);
    return totalContentSize;
}

