    // Write the length of the LinkedBuffer
    out.writeInt(node.size);
    // Write each element of the LinkedBuffer directly to out
    for (int i = 0; i < node.size(); i++) {
        out.write(node.get(i));
    }
    // Return the total size of the buffer written
    return node.size() * node.elementSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    out.writeInt(node.size());
    for (byte b : node.data) {
        out.write(b);
    }
    int totalSize = node.size() * 4 + node.data.length;
    return totalSize;
}

