public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 11) {
        return (int) Math.ceil(Math.sqrt(desiredCapacity));
    }

    int candidate = (int) Math.ceil(Math.sqrt(desiredCapacity));
    if (candidate * candidate == desiredCapacity) {
        candidate += 1;
    }

    while (!isPrime(candidate)) {
        candidate += 2;
    }

    return candidate;
}

private static int nextPrime(int desiredCapacity){
    int capacity = desiredCapacity == 0 ? 1 : desiredCapacity;
    if (capacity < 0) {
        throw new IllegalArgumentException("Desired capacity must be non-negative");
    }

    int prime = nextPrimeAbove(capacity);
    if (prime >= 1024) {
        return (int) (prime * 0.99);
    }
    return prime;
}

private static int nextPrimeAbove(int capacity) {
    capacity--;
    for (int i = 3; i * i <= capacity; i += 2) {
        if ( capacity % i == 0) {
            capacity += 2;
        }
    }
    return capacity;
}

