GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null) {
        throw new IllegalArgumentException("Tour set must not be null");
    }
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }

    GraphPath<V, E> path = new GraphPath<>();
    for (E edge : tour) {
        path.addVertex(graph.getEdgeTails().get(edge).getVe());
        path.addEdge(edge);
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    // Find the nodes in the graph from the edges
    Set<V> visitedNodes = new HashSet<>();
    for (E edge : tour) {
        V src = edge.getSource();
        V dst = edge.getTarget();
        if (!visitedNodes.contains(src)) {
            visitedNodes.add(src);
            // Initialize the current node and edge list
            Set<E> currentEdgeList = new HashSet<>();
            List<V> path = new ArrayList<>();
            while (src != dst) {
                if (!visitedNodes.contains(dst)) {
                    visitedNodes.add(dst);
                    currentEdgeList.add(edge);
                    path.add(dst);
                }
                edge = graph.getEdge(src, dst);
                if (edge == null) break;
                src = edge.getSource();
            }
            path.add(src);
            Collections.reverse(path);
            // Restore the previous node and edge list
            while (!currentEdgeList.isEmpty()) {
                graph.addEdge(path.remove(0), path.get(0));
                currentEdgeList.remove(0);
            }
        }
    }
    return new GraphPathImpl<>(path);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Construct a new GraphPath
    GraphPath<V,E> path = new GraphPath<>();

    // Iterate through each edge in the tour
    for (E edge : tour) {
        // Retrieve the source and target vertices for the current edge
        V source = path.getTarget();
        V target = graph.getEdgeSource(edge);

        // Add an edge to the path
        path.addEdge(source, target);
    }

    // Return the constructed graph path
    return path;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        // Check if the input arguments are valid
        if (tour == null || graph == null) {
            throw new IllegalArgumentException("Input arguments cannot be null");
        }

        // Create a new graph path
        GraphPath<V, E> path = new GraphPath<>();

        // Initialize the current node
        V currentNode = tour.iterator().next();

        // Traverse the tour
        for (E edge : tour) {
            // Add an edge to the path
            path.addEdge(currentNode, edge);

            // Move to the next node
            currentNode = graph.getEdgeTarget(edge);
        }

        return path;
