    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            switch (input.charAt(i)) {
                case '"':
                    sb.append('"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                default:
                    sb.append("\\");
                    sb.append((char) c);
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

