                } else if (nextChar == '"') {
                    sb.append('"');
                } else if (nextChar == '\\') {
                    sb.append('\\');
                } else {
                    // Handle unsupported escape sequences (like \uXXXX)
                    sb.append('\\').append((char) nextChar).append((char) nextChar);
                }
            } else {
                // Handle strings longer than 1 character
                sb.append("\\\\");
