private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices == null || graph == null) {
        throw new IllegalArgumentException("Inputs cannot be null");
    }

    Set<E> edgesInSubgraph = new HashSet<>();
    Set<V> remainingVertices = new HashSet<>(vertices);

    // Find all edges within the induced subgraph
    for (V vertex : remainingVertices) {
        List<SimpleEdge<V, E>> adjacentEdges = graph.edgesConnectingTo(vertex);
        for (SimpleEdge<V, E> edge : adjacentEdges) {
            edgesInSubgraph.add(edge);
        }
    }

    // Check if all vertices are directly connected around the induced subgraph
    int maxDegree = 0;
    for (V vertex : remainingVertices) {
        int degree = (int) graph.edgesConnectingTo(vertex).size();
        if (degree > maxDegree) {
            maxDegree = degree;
        }
    }

    return maxDegree == vertices.size();
}

private static <V, E> boolean isClique(final Graph<V, E> graph, final Set<V> vertices) {
    if (vertices.size() < 2) {
        return true; // A vertex is the ground for a smaller clique on itself, or the graph has no vertices
    }

    for (V v : vertices) {
        Set<V> visitedVertices = new HashSet<>();
       aversalDFS(graph, v, visitedVertices);
        if (visitedVertices.size() != vertices.size()) {
            return false; // The induced graph is not a clique
        }
    }
    return true;
}

private static <V, E> void traversalDFS(final Graph<V, E> graph, final V currentVertex, final Set<V> visitedVertices) {
    if (visitedVertices.contains(currentVertex)) {
        return; // Vertex has already been visited
    }
    visitedVertices.add(currentVertex);

    for (E edge : graph.edgesOf(currentVertex)) {
        traversalDFS(graph, graph.oppositeVertexOf(currentVertex, edge), visitedVertices);
    }
}

