private int binarySearch(List<K> keys, int targetIndex) {
    int left = 0;
    int right = keys.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        int midValue = keys.get(mid);
        if (midValue == targetIndex) {
            return midValue;
        } else if (midValue < targetIndex) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

